using System;using System.Collections.Generic;using System.IO;using CosmicBlock.Core;using CosmicBlock.UI;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine;
public static class Sprint65PlayProbe {
 static GameSession session;static GameFlowController flow;static PlanetRestorationView view;static int stage,frames,oldEnergy,oldVersion;static double started,wait;static string errors="";static readonly List<string> results=new List<string>();
 public static void Run(){oldEnergy=PlayerPrefs.GetInt(PlanetRestoration.DefaultKey,0);oldVersion=PlayerPrefs.GetInt(PlanetRestoration.VersionKey,0);PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,0);PlayerPrefs.SetInt(PlanetRestoration.VersionKey,PlanetRestoration.CurrentVersion);PlayerPrefs.Save();TestDomain();EditorSceneManager.OpenScene(Sprint6Builder.ScenePath);started=EditorApplication.timeSinceStartup;stage=frames=0;Application.logMessageReceived+=Log;EditorApplication.update+=Check;EditorApplication.EnterPlaymode();}
 static void TestDomain(){int[] e={0,10,99,100,101,199,200,299,300,399,400};int[] st={1,1,1,2,2,2,3,3,4,4,5};int[] se={0,10,99,0,1,99,0,99,0,99,100};for(int i=0;i<e.Length;i++){Req(PlanetRestoration.StageForEnergy(e[i])==st[i],"stage "+e[i]);Req(PlanetRestoration.StageEnergyForTotal(e[i])==se[i],"stage energy "+e[i]);Req(!string.IsNullOrEmpty(PlanetRestoration.NameForStage(st[i])),"name");}foreach(var pair in new[]{new[]{95,10,105},new[]{95,25,120},new[]{190,25,215},new[]{395,70,400}}){string k="CB65."+Guid.NewGuid(),v=k+".v";PlayerPrefs.SetInt(k,pair[0]);PlayerPrefs.SetInt(v,2);var m=new PlanetRestoration(k,v);m.AddEnergy(pair[1]);Req(m.CurrentEnergy==pair[2],"overflow");PlayerPrefs.DeleteKey(k);PlayerPrefs.DeleteKey(v);}int[] old={0,125,250,375,500},migrated={0,100,200,300,400};for(int i=0;i<old.Length;i++){string k="CB65M."+i,v=k+".v";PlayerPrefs.SetInt(k,old[i]);PlayerPrefs.DeleteKey(v);var m=new PlanetRestoration(k,v);Req(m.CurrentEnergy==migrated[i]&&PlayerPrefs.GetInt(v)==2,"migration "+old[i]);m.Load();Req(m.CurrentEnergy==migrated[i],"migration once");PlayerPrefs.DeleteKey(k);PlayerPrefs.DeleteKey(v);}results.Add("PASS mapping, names, overflow, clamp and one-time 500-to-400 migration.");}
 static void Log(string m,string s,LogType t){if(t==LogType.Error||t==LogType.Exception||t==LogType.Assert)errors+=m+"\n";}
 static void Check(){if(EditorApplication.timeSinceStartup-started>240){Finish(false,"timeout");return;}if(!EditorApplication.isPlaying)return;try{if(stage==0){if(++frames<30)return;session=UnityEngine.Object.FindAnyObjectByType<GameSession>();flow=UnityEngine.Object.FindAnyObjectByType<GameFlowController>();view=UnityEngine.Object.FindAnyObjectByType<PlanetRestorationView>(FindObjectsInactive.Include);flow.Play();int[] x={0,10,25,50,75,90,99};foreach(int n in x){session.DebugSetPlanetEnergy(n);Req(Mathf.Abs(view.ProgressFill-n/100f)<.011f,"fill "+n);}Req(view.FragmentPoolCapacity==12,"fragment pool");session.DebugSetPlanetEnergy(95);session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3)&&session.Restoration.CurrentEnergy==105&&session.State==GameState.Resolving,"clear locks input");wait=EditorApplication.timeSinceStartup;stage=1;return;}if(stage==1){if(EditorApplication.timeSinceStartup-wait<.18)return;Req(view.ActiveFragmentCount>=6&&view.LastFragmentStarts.Length>=6,"flight active from cells");wait=EditorApplication.timeSinceStartup;stage=2;return;}if(stage==2){if(EditorApplication.timeSinceStartup-wait<4.0)return;Req(session.State==GameState.Playing&&view.ShownStage==2&&view.PresentedEnergy==105&&!view.CompletionActive&&view.ActiveFragmentCount==0,"transition completes/unlocks");Req(view.CompletionPlayCount==1,"transition once");int count=view.transform.parent.childCount;session.Retry();flow.ShowHome();flow.Play();Req(!view.FeedbackActive&&!view.CompletionActive&&view.ActiveFragmentCount==0&&session.State==GameState.Playing,"cleanup flows");Req(view.transform.parent.childCount==count,"hierarchy stable");session.DebugSetPlanetEnergy(395);session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3)&&session.Restoration.CurrentEnergy==400,"restored clamp");wait=EditorApplication.timeSinceStartup;stage=3;return;}if(stage==3){if(EditorApplication.timeSinceStartup-wait<4.0)return;Req(session.State==GameState.Playing&&view.ShownStage==5&&view.PresentedEnergy==400,"restored presentation");int c=view.CompletionPlayCount;session.DebugPrepareNextRow();Req(session.TryPlacePiece(session.Slots[0],3,3)&&session.Restoration.CurrentEnergy==400,"restored no overflow");Req(view.CompletionPlayCount==c&&!view.FeedbackActive,"no repeat at restored");Req(errors.Length==0,"runtime errors "+errors);results.Add("PASS exact fill, cell-origin pooled flight, input lock, stage cinematic, cleanup, restored once.");Finish(true,"");}}catch(Exception ex){Finish(false,ex.ToString());}}
 static void Req(bool v,string m){if(!v)throw new Exception("Sprint 6.5 failed: "+m);}static void Finish(bool pass,string fail){EditorApplication.update-=Check;Application.logMessageReceived-=Log;PlayerPrefs.SetInt(PlanetRestoration.DefaultKey,oldEnergy);PlayerPrefs.SetInt(PlanetRestoration.VersionKey,oldVersion);PlayerPrefs.Save();Directory.CreateDirectory("Validation");File.WriteAllText("Validation/sprint65.txt",string.Join("\n",results)+"\n"+(pass?"SPRINT65_PLAY_PASS":fail));if(pass)Debug.Log("SPRINT65_PLAY_PASS");else Debug.LogError(fail);EditorApplication.Exit(pass?0:1);}
}
